INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'highlight', 'n./v.', '/ˈhaɪlaɪt/', '最精彩的部分;要点;强调', 'The highlight of the lecture was how language shapes the way we think.', '讲座最精彩的部分是语言如何塑造我们的思维方式。', 'Language and Mind', 1, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the highlight of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'magnetic', 'adj.', '/mæɡˈnetɪk/', '磁的;有磁性的;有吸引力的', 'Doctors used a magnetic scanner to study the bilingual brain.', '医生用磁性扫描仪研究双语者的大脑。', 'Language and Mind', 2, 0, 'senior', 'wordlist', 'elective2', 'U2', 'magnetic resonance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'resonance', 'n.', '/ˈrezənəns/', '共鸣;共振', 'Magnetic resonance imaging lets scientists watch the brain at work.', '磁共振成像让科学家观察大脑工作的过程。', 'Language and Mind', 3, 0, 'senior', 'wordlist', 'elective2', 'U2', 'magnetic resonance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'imaging', 'n.', '/ˈɪmɪdʒɪŋ/', '成像', 'Brain imaging shows that learning a language changes its structure.', '脑成像显示,学习语言会改变大脑的结构。', 'Language and Mind', 4, 0, 'senior', 'wordlist', 'elective2', 'U2', 'brain imaging', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'scan', 'n./v.', '/skæn/', '扫描检查;扫描;细看', 'The students were given a brain scan before and after the course.', '学生们在课程前后各做了一次脑部扫描。', 'Language and Mind', 5, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a brain scan', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'promising', 'adj.', '/ˈprɒmɪsɪŋ/', '有希望的;有前途的', 'Language learning is a promising way to keep the mind sharp.', '学语言是保持头脑敏锐的一种有希望的方法。', 'Language and Mind', 6, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a promising way', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'enhanced', 'adj.', '/ɪnˈhɑːnst/', '增强的;提高的', 'Bilingual people often enjoy enhanced memory and attention.', '双语者往往拥有更强的记忆力和注意力。', 'Language and Mind', 7, 0, 'senior', 'wordlist', 'elective2', 'U2', 'enhanced memory', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cognitive', 'adj.', '/ˈkɒɡnɪtɪv/', '认知的;感知的', 'Learning a second language brings real cognitive benefits.', '学习第二语言能带来实实在在的认知益处。', 'Language and Mind', 8, 0, 'senior', 'wordlist', 'elective2', 'U2', 'cognitive benefits', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'outperform', 'v.', '/ˌaʊtpəˈfɔːm/', '超过;胜过', 'In some memory tests, bilingual children outperform their classmates.', '在一些记忆测试中,双语儿童的表现胜过同学。', 'Language and Mind', 9, 0, 'senior', 'wordlist', 'elective2', 'U2', 'outperform others', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'journal', 'n.', '/ˈdʒɜːnl/', '期刊;杂志;日志', 'The study was published in a well-known science journal.', '这项研究发表在一份知名的科学期刊上。', 'Language and Mind', 10, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a science journal', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'comprehension', 'n.', '/ˌkɒmprɪˈhenʃn/', '理解;理解力', 'A comprehension task tested how quickly they understood each word.', '一项理解任务测试他们理解每个词的速度。', 'Language and Mind', 11, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a comprehension task', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'corresponding', 'adj.', '/ˌkɒrɪˈspɒndɪŋ/', '相应的;对应的', 'They had to choose the corresponding image for each spoken word.', '他们要为每个听到的词选出相应的图片。', 'Language and Mind', 12, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the corresponding image', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'trick', 'n./v.', '/trɪk/', '诀窍;错觉;欺骗', 'The trick was that a similar-sounding word was added to confuse them.', '诀窍在于加入了一个发音相近的词来迷惑他们。', 'Language and Mind', 13, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the trick was that', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'distracting', 'adj.', '/dɪˈstræktɪŋ/', '使分心的;干扰的', 'Bilingual speakers were better at ignoring the distracting words.', '双语者更善于忽略那些干扰的词。', 'Language and Mind', 14, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the distracting word', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'target', 'n.', '/ˈtɑːɡɪt/', '目标;对象;靶子', 'Each list contained one target word and several similar ones.', '每张词表都含有一个目标词和几个相似的词。', 'Language and Mind', 15, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the target word', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'versus', 'prep.', '/ˈvɜːsəs/', '与……相对;对比', 'The test compared simple pairs such as ''candy'' versus ''candle''.', '测试比较了像 candy 与 candle 这样的简单词对。', 'Language and Mind', 16, 0, 'senior', 'wordlist', 'elective2', 'U2', 'candy versus candle', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'filter', 'v./n.', '/ˈfɪltə(r)/', '过滤;筛除;滤器', 'A good listener can filter out sounds that do not matter.', '好的倾听者能过滤掉无关紧要的声音。', 'Language and Mind', 17, 0, 'senior', 'wordlist', 'elective2', 'U2', 'filter out', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'considerable', 'adj.', '/kənˈsɪdərəbl/', '相当大的;相当多的', 'Speaking two languages has considerable benefits for the brain.', '会说两种语言对大脑有相当大的好处。', 'Language and Mind', 18, 0, 'senior', 'wordlist', 'elective2', 'U2', 'considerable benefits', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'bilingual', 'adj.', '/baɪˈlɪŋɡwəl/', '会说两种语言的;双语的', 'Bilingual people can switch between two languages with ease.', '双语者能够轻松地在两种语言之间切换。', 'Language and Mind', 19, 0, 'senior', 'wordlist', 'elective2', 'U2', 'bilingual children', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cell', 'n.', '/sel/', '细胞', 'Learning a language challenges the grey cells in our brain.', '学习语言会锻炼我们大脑里的灰色细胞。', 'Language and Mind', 20, 0, 'senior', 'wordlist', 'elective2', 'U2', 'grey cells', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'significantly', 'adv.', '/sɪɡˈnɪfɪkəntli/', '显著地;明显地', 'Language can significantly shape the way we see the world.', '语言能显著地塑造我们看待世界的方式。', 'Language and Mind', 21, 0, 'senior', 'wordlist', 'elective2', 'U2', 'significantly shape', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'recognise', 'v.', '/ˈrekəɡnaɪz/', '识别;辨认;承认', 'Russian speakers recognise shades of blue faster than English speakers.', '俄语者比英语者更快地辨认出蓝色的深浅。', 'Language and Mind', 22, 0, 'senior', 'wordlist', 'elective2', 'U2', 'recognise the difference', '美式拼 recognize;美音 /ˈrekəɡnaɪz/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'differ', 'v.', '/ˈdɪfə(r)/', '不同;相异', 'Languages differ in how they describe the same accident.', '各种语言在描述同一场意外时各不相同。', 'Language and Mind', 23, 0, 'senior', 'wordlist', 'elective2', 'U2', 'differ in', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'structure', 'n.', '/ˈstrʌktʃə(r)/', '结构;构造;体系', 'The structure of a language can mirror how its speakers think.', '一门语言的结构能映照出使用者的思维方式。', 'Language and Mind', 24, 0, 'senior', 'wordlist', 'elective2', 'U2', 'brain structure', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'reality', 'n.', '/riˈæləti/', '现实;实际;真实情况', 'Each language seems to create its own kind of reality.', '每种语言似乎都创造出自己的一种现实。', 'Language and Mind', 25, 0, 'senior', 'wordlist', 'elective2', 'U2', 'create a reality', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'affect', 'v.', '/əˈfekt/', '影响;作用于', 'The words we use may affect the decisions we make.', '我们使用的词语可能影响我们做出的决定。', 'Language and Mind', 26, 0, 'senior', 'wordlist', 'elective2', 'U2', 'affect our decisions', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'blame', 'n./v.', '/bleɪm/', '责备;归咎;责任', 'Some languages make us less likely to blame a person for an accident.', '有些语言让我们不太会把意外归咎于某个人。', 'Language and Mind', 27, 0, 'senior', 'wordlist', 'elective2', 'U2', 'blame somebody', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'soul', 'n.', '/səʊl/', '灵魂;心灵;精神', 'To have a second language, it is said, is to have a second soul.', '人们说,拥有第二语言就是拥有第二个灵魂。', 'Language and Mind', 28, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a second soul', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'elsewhere', 'adv.', '/ˌelsˈweə(r)/', '在别处;到别处', 'It is not really about how people elsewhere think, but about how you think.', '这其实无关别处的人如何思考,而关乎你如何思考。', 'Language and Mind', 29, 0, 'senior', 'wordlist', 'elective2', 'U2', 'people elsewhere', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'brilliant', 'adj.', '/ˈbrɪliənt/', '聪明的;杰出的;明亮的', 'The variety of languages reveals how brilliant the human mind is.', '语言的多样性揭示了人类心智多么卓越。', 'Language and Mind', 30, 0, 'senior', 'wordlist', 'elective2', 'U2', 'brilliant mind', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'effect', 'n.', '/ɪˈfekt/', '影响;效果;结果', 'Language can have early effects on a child''s thinking.', '语言会对儿童的思维产生早期影响。', 'Language and Mind', 31, 0, 'senior', 'wordlist', 'elective2', 'U2', 'early effects', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'impact', 'n.', '/ˈɪmpækt/', '影响;冲击;撞击', 'Small word choices can have a real impact on our judgement.', '细小的用词选择能对我们的判断产生真实的影响。', 'Language and Mind', 32, 0, 'senior', 'wordlist', 'elective2', 'U2', 'have an impact', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'flexible', 'adj.', '/ˈfleksəbl/', '灵活的;可变通的;柔韧的', 'Our minds are flexible enough to learn many languages.', '我们的心智足够灵活,能学会许多种语言。', 'Language and Mind', 33, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a flexible mind', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'variety', 'n.', '/vəˈraɪəti/', '多样;种类;变化', 'There is a beautiful variety of languages in the world.', '世界上有着丰富多样的语言。', 'Language and Mind', 34, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a variety of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'distinguish', 'v.', '/dɪˈstɪŋɡwɪʃ/', '区分;辨别;使有别于', 'Even unborn babies can distinguish between two languages.', '甚至尚未出生的婴儿也能区分两种语言。', 'Language and Mind', 35, 0, 'senior', 'wordlist', 'elective2', 'U2', 'distinguish between', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mindset', 'n.', '/ˈmaɪndset/', '思维方式;心态', 'Learning a language can give you a more global mindset.', '学习一门语言能让你拥有更全球化的思维方式。', 'Language and Mind', 36, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a global mindset', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'hypothesis', 'n.', '/haɪˈpɒθəsɪs/', '假说;假设', 'The famous hypothesis claims that language shapes thought.', '那个著名的假说认为语言塑造思维。', 'Language and Mind', 37, 0, 'senior', 'wordlist', 'elective2', 'U2', 'the Sapir-Whorf hypothesis', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'linguist', 'n.', '/ˈlɪŋɡwɪst/', '语言学家', 'Many linguists are working hard to save dying languages.', '许多语言学家正在努力拯救濒临消亡的语言。', 'Language and Mind', 38, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a team of linguists', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'acquisition', 'n.', '/ˌækwɪˈzɪʃn/', '习得;获得;取得', 'Input and output both matter in language acquisition.', '在语言习得中,输入和输出都很重要。', 'Language and Mind', 39, 0, 'senior', 'wordlist', 'elective2', 'U2', 'language acquisition', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'perceive', 'v.', '/pəˈsiːv/', '感知;察觉;看待', 'The language we speak may change how we perceive the world.', '我们所说的语言可能改变我们感知世界的方式。', 'Language and Mind', 40, 0, 'senior', 'wordlist', 'elective2', 'U2', 'perceive the world', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'determine', 'v.', '/dɪˈtɜːmɪn/', '决定;查明;确定', 'Some argue that language can even determine our thoughts.', '有人主张语言甚至能决定我们的思想。', 'Language and Mind', 41, 0, 'senior', 'wordlist', 'elective2', 'U2', 'determine our thoughts', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'demanding', 'adj.', '/dɪˈmɑːndɪŋ/', '要求高的;费力的', 'The students followed a demanding language-learning programme.', '学生们参加了一个要求很高的语言学习项目。', 'Language and Mind', 42, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a demanding programme', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'switch', 'v./n.', '/swɪtʃ/', '转换;切换;开关', 'The effort to switch between languages strengthens the brain.', '在语言之间切换所付出的努力能强化大脑。', 'Language and Mind', 43, 0, 'senior', 'wordlist', 'elective2', 'U2', 'switch between', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'attention', 'n.', '/əˈtenʃn/', '注意;关注;注意力', 'Different languages make us pay attention to different things.', '不同的语言让我们关注不同的事物。', 'Language and Mind', 44, 0, 'senior', 'wordlist', 'elective2', 'U2', 'pay attention to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'endangered', 'adj.', '/ɪnˈdeɪndʒəd/', '濒危的;有灭绝危险的', 'There are many endangered languages in Australia today.', '如今澳大利亚有许多濒危语言。', 'Language and Mind', 45, 0, 'senior', 'wordlist', 'elective2', 'U2', 'endangered languages', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'predict', 'v.', '/prɪˈdɪkt/', '预测;预言', 'Experts predict that half of all languages may disappear.', '专家预测,所有语言中或许有一半会消失。', 'Language and Mind', 46, 0, 'senior', 'wordlist', 'elective2', 'U2', 'predict that', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'have an impact on', 'phr.', '/hæv ən ˈɪmpækt ɒn/', '对……有影响', 'The words people use can have an impact on how they feel.', '人们使用的词语能对他们的感受产生影响。', 'Language and Mind', 47, 0, 'senior', 'wordlist', 'elective2', 'U2', 'have an impact on', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'second language', 'phr.', '/ˈsekənd ˈlæŋɡwɪdʒ/', '第二语言;外语', 'A second language opens up a new way of looking at the world.', '第二语言开启了一种看待世界的新方式。', 'Language and Mind', 48, 0, 'senior', 'wordlist', 'elective2', 'U2', 'a second language', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u2.01', '①主语从句(句首):连接词选择', 'A2', 11, '上外版选择性必修第二册 U2 — 名词性从句放句首作主语时:从句完整且陈述事实用 that;表''是否''的疑问用 whether(不用 if);从句缺主语或宾语(=所…的事物)用 what;问方式/程度用 how;问原因用 why。', 1, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u2.02', '②it 作形式主语:真正主语后置', 'A2', 11, '上外版选择性必修第二册 U2 — 用 it 作形式主语、真正的主语从句后置:It is + 形容词/名词/过去分词 + that(陈述)/whether(是否)/what·how·why(疑问词)从句。如 It is true that… / It is unknown whether… / It is amazing how…。', 2, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se2u2.03', '③表语从句(系动词 be 之后)', 'A2', 11, '上外版选择性必修第二册 U2 — 名词性从句跟在系动词 be 后作表语;连接词由主语名词与从句意义决定:fact/truth/idea/belief/point + that;question/problem + whether;The reason is that…;That is why…;主语为 this/that/all、从句缺成分 + what。', 3, 'elective2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.01'), '"____ our language really shapes our thoughts has interested scientists for years."', 'Whether', 'What', 'If', 'Because', 'A', '句首主语从句表''是否''的待解疑问 → whether(不用 if);从句完整,what 多余。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.01'), '"____ surprised the researchers most was the speed of the answers."', 'That', 'What', 'Whether', 'It', 'B', '从句缺主语(____ surprised…)→ what(=the thing that)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.01'), '"____ language can shape thought is now widely accepted by experts."', 'What', 'Whether', 'That', 'How', 'C', '从句完整、陈述被接受的事实 → that。', 2, 3, 'mcq');
