INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"One common belief is ____ any language can be mastered with practice."', 'whether', 'what', 'why', 'that', 'D', '主语 belief、从句陈述内容 → that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The reason is ____ their language makes them notice such details."', 'that', 'why', 'what', 'how', 'A', '''The reason is + 表语从句''用 that(不用 why)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The problem is ____ we can ever fully translate one language into another."', 'that', 'whether', 'what', 'how', 'B', '主语 problem、表''能否''的疑问 → whether。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"His greatest fear is ____ his mother tongue will die out."', 'whether', 'what', 'that', 'why', 'C', '表语从句陈述所担心的内容 → that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"That is ____ Russian speakers react to shades of blue so fast."', 'that', 'what', 'how', 'why', 'D', '''That is why…''说明原因 → why。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The first thing she noticed was ____ the two words sounded almost alike."', 'that', 'whether', 'what', 'how', 'A', '表语从句陈述她注意到的事实 → that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"This is ____ language can quietly do to our thinking."', 'that', 'what', 'whether', 'why', 'B', '从句缺宾语(do ____ to our thinking)→ what。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The point is ____ small words can steer big decisions."', 'whether', 'what', 'that', 'why', 'C', '主语 point、从句陈述要点 → that。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"What matters most is ____ you pay attention to, not where you live."', 'that', 'whether', 'how', 'what', 'D', '从句缺宾语(pay attention to ____)→ what。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The mystery is ____ so many languages are disappearing today."', 'why', 'that', 'what', 'whether', 'A', '主语 mystery、追问原因 → why。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"Her firm belief is ____ every language opens a new window on the world."', 'whether', 'that', 'what', 'how', 'B', '主语 belief、从句陈述信念 → that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The strange thing is ____ we rarely ask why we think as we do."', 'whether', 'what', 'that', 'why', 'C', '从句完整、陈述''奇怪的事实'' → that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The whole point of her talk was ____ language shapes us all."', 'whether', 'what', 'how', 'that', 'D', '从句陈述演讲要点 → that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The open question is ____ thought can exist without any words."', 'whether', 'that', 'what', 'why', 'A', '主语 question、表''能否''的疑问 → whether。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The best part is ____ learning a language actually reshapes the brain."', 'whether', 'that', 'what', 'how', 'B', '从句陈述''最棒的部分''这一事实 → that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"His only doubt is ____ a written record can keep a language alive."', 'that', 'what', 'whether', 'why', 'C', '主语 doubt、表''能否''的疑问 → whether。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective2' AND unit='U2' AND code='se2u2.03'), '"The amazing fact is ____ no single language can capture every idea."', 'whether', 'what', 'why', 'that', 'D', '主语 fact、从句陈述事实 → that。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Does Language Shape the Mind?', 'One of the oldest questions about language is simple to ask but hard to answer: does the language we speak change the way we think? A scholar named Benjamin Whorf once went very far. He claimed that language does not only influence thought, but actually decides it. In its strongest form, this idea has been turned down by many psychologists. After all, it is not hard to find thoughts that need no words at all. A baby, a dog, or a musician can clearly think without sentences. Yet a softer form of the idea is still hard to argue against. Few people would deny that the language we use can, at least a little, colour the way we see the world. So most experts today take a middle view. Language is probably not a prison for the mind, but it is more like a pair of glasses. It does not decide what is out there, but it can gently change what we notice first and what we easily forget.', '议论·语言与思维之争', 169, '[{"q":"What did Benjamin Whorf claim in his strongest view?","answer":"A","options":["Language completely decides how we think.","Language has no effect on thought at all.","Thought always comes before any language.","Words and thoughts are totally unrelated."],"explanation":"原文 Whorf 称语言''determines thought''的转述,即语言完全决定思维。"},{"q":"Why do many psychologists reject the strongest form?","answer":"B","options":["Because babies are unable to think at all.","Because people can clearly think without using words.","Because language is far too simple to study.","Because no one studies language today."],"explanation":"原文''thoughts that need no words''(婴儿、狗、音乐家)说明能无词而思 → 否定最强版本。"},{"q":"What middle view do most experts hold now?","answer":"A","options":["Language gently shapes what we notice, not what exists.","Language fully controls outside reality.","Language has zero influence on the mind.","Language is a complete prison for thought."],"explanation":"末段''a pair of glasses…gently change what we notice''的转述。"}]'::jsonb, '[{"word":"influence","cn":"影响"},{"word":"psychologist","cn":"心理学家"},{"word":"deny","cn":"否认"}]'::jsonb, 2, 'elective2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Russian Blues', 'Not every language cuts up the rainbow in the same way. English has one main word for blue, whether the sky is pale or deep. Russian is different. It has no single word that simply means ''blue''. Instead, Russian speakers must choose between ''goluboy'' for light blue and ''siniy'' for dark blue, just as English speakers choose between red and pink. Does this habit change anything real? Scientists decided to test it. They showed people two squares of colour and asked, as fast as possible, whether the shades were the same or different. Russian speakers were quicker when one square was light blue and the other dark blue, because their language forces them to mark that border every day. English speakers, who file both under a single word, were a little slower. The study suggests that the words we grow up with can train our eyes without our noticing. We are not born seeing colour this way; our language quietly teaches us where one shade ends and the next begins.', '说明·颜色词与感知', 170, '[{"q":"How does Russian treat the colour blue?","answer":"B","options":["It has one single word for every shade of blue.","It uses separate words for light and dark blue.","It has no word for blue at all.","It uses the same word as it does for red."],"explanation":"原文''goluboy''与''siniy''分指浅蓝、深蓝的转述。"},{"q":"What were people asked to do in the test?","answer":"C","options":["Name every colour in the room.","Paint two blue squares by hand.","Judge quickly whether two shades matched.","Translate the Russian colour words."],"explanation":"原文''asked…whether the shades were the same or different''的转述。"},{"q":"What does the study suggest about language and colour?","answer":"D","options":["People are born seeing all colours the same way.","Colour words have no effect on the eyes.","Russian speakers cannot see dark blue.","Our language can train how fast we tell shades apart."],"explanation":"末段''words…can train our eyes''的转述。"}]'::jsonb, '[{"word":"rainbow","cn":"彩虹"},{"word":"pale","cn":"浅的;淡的"},{"word":"shade","cn":"色度;浓淡"}]'::jsonb, 2, 'elective2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Whose Fault Was It?', 'Imagine a waiter who trips, and a glass falls and breaks. How would you describe it? In English, we usually say, ''He broke the glass,'' naming the person even when nobody meant any harm. Spanish speakers often prefer a different shape: ''The glass broke,'' as if the object had acted on its own. When the event is a pure accident, many languages avoid pointing at a person at all. This small difference may do more than it seems. In one study, people watched the same short films of accidents. Later, English speakers were better at remembering who had been involved, while Spanish speakers remembered the action more than the actor. Their languages had quietly told them what to keep in mind. Some researchers think this can even touch ideas like blame and punishment. If your language always names a doer, you may be quicker to ask whose fault it was. Language does not force us to judge, but it can lean us, softly, in one direction rather than another.', '说明·描述意外与归咎', 169, '[{"q":"How do English and Spanish often differ when describing an accident?","answer":"A","options":["English names the person; Spanish stresses the event itself.","Both of them always blame the person.","Spanish always names the guilty person.","Neither one mentions the accident."],"explanation":"原文''He broke the glass''对''The glass broke''的对比转述。"},{"q":"What did the two groups remember differently after the films?","answer":"B","options":["Both groups forgot the films completely.","English speakers recalled who was involved more easily.","Spanish speakers recalled the person better.","Nobody remembered any action."],"explanation":"原文''English speakers were better at remembering who had been involved''的转述。"},{"q":"What larger idea might this difference affect?","answer":"C","options":["The price of the broken glasses.","The speed of the waiters.","How readily we assign blame.","The colour of the short films."],"explanation":"原文''ideas like blame and punishment…quicker to ask whose fault''的转述。"}]'::jsonb, '[{"word":"trip","cn":"绊倒"},{"word":"actor","cn":"行为者;做事的人"},{"word":"punishment","cn":"惩罚"}]'::jsonb, 2, 'elective2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'For a Better Brain', 'Learning a new language can feel a little like magic, but the real magic happens inside the brain. Researchers in Sweden once studied two groups of students. One group began a hard language course, while the other studied medicine and science. Both groups had brain scans at the start and again three months later. Only in the language learners did the scans show clear changes in brain structure. In another study, people were asked to listen to a word and pick the matching picture from four. The trick was that one picture had a name that sounded close to the target, such as ''candy'' and ''candle''. People who spoke two languages found it easier to ignore the distracting choice, while those who spoke only one had to work harder. Other research links speaking two languages to a later start of memory disease, sometimes by several years. None of this means a bilingual person is simply ''smarter''. It means the daily effort of switching between languages gives the brain a healthy, lasting workout.', '说明·双语与大脑', 172, '[{"q":"What did the Swedish brain scans reveal?","answer":"D","options":["Both groups'' brains changed in the same way.","No brain changed at all in three months.","Only the science students'' brains changed.","Only the language learners'' brain structure changed."],"explanation":"原文''brain structure changed only in the language learning group''的转述。"},{"q":"Why was the ''candy/candle'' part tricky?","answer":"A","options":["One picture''s name sounded like the target word.","The pictures were too dark to see.","There were no pictures shown at all.","The words were in a foreign script."],"explanation":"原文''a distracting word…sounds similar to the target word''的转述。"},{"q":"What does the writer conclude about bilingual brains?","answer":"B","options":["Bilingual people are always far cleverer.","Switching languages keeps the brain fit, not simply smarter.","Two languages clearly harm the brain.","Language has no effect on memory."],"explanation":"末段''does make your brain healthier…a workout''的转述,而非简单''更聪明''。"}]'::jsonb, '[{"word":"magic","cn":"魔法;奇迹"},{"word":"medicine","cn":"医学;药"},{"word":"workout","cn":"锻炼"}]'::jsonb, 2, 'elective2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Languages Are Disappearing', 'You probably know that many animals and plants are in danger, but languages can vanish too. There are around seven thousand living languages today, yet experts warn that more than half could be gone by the end of this century. When the last speaker of a language dies, something more than words is lost. Each language carries its own stories, jokes, songs, and ways of naming the plants and seasons around it. Much of that knowledge has never been written down, so it simply disappears with the final voice. In Australia, for example, hundreds of languages were once spoken, but only a small number are still used every day. For many communities, their language sits at the very heart of who they are. It links them to their land, their history, and their elders. That is why linguists travel to far and quiet places, recording speakers and helping younger people learn. Saving a language is hard work, but it keeps a whole way of seeing the world alive.', '说明·濒危语言', 168, '[{"q":"What warning do experts give about today''s languages?","answer":"C","options":["All of them are now perfectly safe.","They will all soon become English.","Over half may disappear within this century.","None of them has any speakers left."],"explanation":"原文''more than half will have disappeared by the end of the century''的转述。"},{"q":"Why is losing a language more than losing words?","answer":"D","options":["Only its spelling rules are lost.","Words are very easy to replace.","Nothing of value is actually lost.","Unwritten knowledge and stories vanish along with it."],"explanation":"原文''much knowledge goes with it…never been written down''的转述。"},{"q":"Why do linguists travel to far and quiet places?","answer":"A","options":["To record speakers and help young people learn.","To sell printed dictionaries.","To stop people from speaking.","To search for new animals."],"explanation":"原文''linguists who are studying and trying to save…languages''的转述。"}]'::jsonb, '[{"word":"vanish","cn":"消失"},{"word":"community","cn":"社区;群体"},{"word":"elder","cn":"长者;前辈"}]'::jsonb, 2, 'elective2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Time, Space and Words', 'Languages can shape something as basic as how we picture time. In English, people often place time on a line that runs from left to right: last week is behind us, and next week lies ahead. Speakers of some Chinese expressions, by contrast, may also think of time as moving up and down, with an earlier month ''above'' and a later month ''below''. Neither way is right or wrong, but each can guide the pictures that form in our minds. Space works in a similar way. A few languages have no words for ''left'' and ''right'' at all. Instead, their speakers always use north, south, east, and west, even indoors. To do this, they must keep track of direction all the time, and they become remarkably good at it. A child raised with such a language can point to the north without thinking. These habits show how a language can quietly train the mind, shaping not only the words we use but the very maps we carry inside our heads.', '说明·时间与空间的语言', 170, '[{"q":"How do many English speakers picture time?","answer":"B","options":["As a circle with no beginning.","As a line running from left to right.","As something moving up and down.","As standing completely still."],"explanation":"原文''a line…left-right terms…next week lies ahead''的转述。"},{"q":"What is special about languages without ''left'' and ''right''?","answer":"C","options":["Their speakers cannot describe space at all.","They never mention any direction.","Their speakers rely on compass directions instead.","They use only the words ''up'' and ''down''."],"explanation":"原文''always use north, south, east, and west''的转述。"},{"q":"What do these examples show about language?","answer":"D","options":["It has no link to the way we think.","It only changes our spelling habits.","It makes people forget all directions.","It can quietly train how the mind maps the world."],"explanation":"末段''quietly train the mind…maps we carry inside our heads''的转述。"}]'::jsonb, '[{"word":"ahead","cn":"在前面;向前"},{"word":"direction","cn":"方向"},{"word":"remarkably","cn":"非凡地;惊人地"}]'::jsonb, 2, 'elective2', 'U2', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'My First Week Abroad', 'When I arrived in London as an exchange student, I quickly learned that having a (1)____ language was like owning a second pair of eyes. At first, switching between Chinese and English was (2)____, and my head felt tired by lunchtime. My host mother told me not to (3)____ myself for every small mistake. She said that the daily effort to (4)____ between two languages would actually make my brain stronger. Slowly, I began to (5)____ sounds that I had never noticed before. What surprised me most was (6)____ a single kind sentence from a stranger could lift my whole day. I started to keep a (7)____ in which I wrote down new words every evening. Reading it later, I could clearly (8)____ how much progress I had made. By the end of the week, English no longer felt like a wall but like a door that had begun to (9)____ up. The (10)____ is that learning a language slowly changes the way you see everything.', 166, 2, '[{"q":"1","answer":"A","options":["second","quiet","empty","silent"],"explanation":"a second language 第二语言。"},{"q":"2","answer":"B","options":["easy","demanding","silent","cheap"],"explanation":"下文''head felt tired''→ demanding 费力的。"},{"q":"3","answer":"C","options":["praise","thank","blame","help"],"explanation":"not to blame myself 不要责备自己。"},{"q":"4","answer":"D","options":["sleep","pay","sell","switch"],"explanation":"switch between two languages 在两种语言间切换。"},{"q":"5","answer":"A","options":["recognise","forget","lose","drop"],"explanation":"recognise sounds 辨认出声音。"},{"q":"6","answer":"B","options":["why","that","where","whether"],"explanation":"表语从句陈述事实 → that。"},{"q":"7","answer":"C","options":["ticket","price","journal","map"],"explanation":"keep a journal 记日志。"},{"q":"8","answer":"D","options":["hide","lose","sell","see"],"explanation":"see how much progress 看出进步。"},{"q":"9","answer":"A","options":["open","break","fall","shut"],"explanation":"open up 打开;拓展。"},{"q":"10","answer":"B","options":["price","truth","noise","weather"],"explanation":"The truth is that… 表语从句结构。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'Grandma''s Words', 'My grandmother speaks an old village (1)____ that very few young people still use. When I was small, I thought it sounded strange, and I could not (2)____ many of her words. Now I understand that her way of speaking carries (3)____ that no textbook could ever hold. Each phrase is tied to the fields, the festivals, and the (4)____ of our family. Sadly, languages like hers are (5)____, and experts (6)____ that many will disappear within fifty years. When the last speaker is gone, much local (7)____ goes with them. That is (8)____ I have decided to record my grandmother. Every weekend I sit with her and ask her to tell old stories. The (9)____ is whether young people like me can keep these words alive. I believe even a small effort can have a real (10)____ on the future of a language.', 144, 2, '[{"q":"1","answer":"C","options":["machine","ticket","dialect","garden"],"explanation":"an old dialect 一种古老方言。"},{"q":"2","answer":"D","options":["sell","throw","cook","follow"],"explanation":"could not follow her words 听不懂她的话。"},{"q":"3","answer":"A","options":["knowledge","noise","money","traffic"],"explanation":"carries knowledge 承载知识。"},{"q":"4","answer":"B","options":["prices","stories","engines","tickets"],"explanation":"the stories of our family 家族的故事。"},{"q":"5","answer":"C","options":["modern","cheap","endangered","loud"],"explanation":"languages are endangered 语言濒危。"},{"q":"6","answer":"D","options":["forget","sell","hide","predict"],"explanation":"experts predict that… 专家预测。"},{"q":"7","answer":"A","options":["knowledge","money","noise","weather"],"explanation":"much local knowledge 许多地方知识。"},{"q":"8","answer":"B","options":["what","why","whether","how"],"explanation":"That is why… 表语从句说明原因。"},{"q":"9","answer":"C","options":["price","weather","question","noise"],"explanation":"The question is whether… 问题在于能否。"},{"q":"10","answer":"D","options":["price","noise","holiday","impact"],"explanation":"have an impact on 对……有影响。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'How English Changed My World', 'Before I learned English well, I thought a language was just a set of words for naming things. Now I (1)____ that it is much more than that. Learning English has slowly changed the way I (2)____ the world. For example, English made me notice (3)____ differently people can describe the very same event. It also taught me that there is more than one (4)____ behind every story. Sometimes I read an English poem and feel a kind of (5)____ deep inside me, as if the words were ringing a bell. My teacher says that to have a second language is to gain a second (6)____. That idea once sounded strange, but now I fully (7)____ it. The most (8)____ part is that my Chinese has improved too, because comparing the two languages makes each one clearer. (9)____ matters is not which language is better, but how each one opens a new window. The (10)____ is that every language I learn makes me a slightly different person.', 167, 2, '[{"q":"1","answer":"A","options":["realise","forget","doubt","deny"],"explanation":"now I realise 如今我意识到。"},{"q":"2","answer":"B","options":["sell","perceive","cook","throw"],"explanation":"the way I perceive the world 我感知世界的方式。"},{"q":"3","answer":"C","options":["why","whether","how","where"],"explanation":"notice how differently… 名词性从句,表程度/方式用 how。"},{"q":"4","answer":"D","options":["price","ticket","engine","reality"],"explanation":"more than one reality 不止一种现实。"},{"q":"5","answer":"A","options":["resonance","hunger","traffic","silence"],"explanation":"feel a kind of resonance 感到共鸣。"},{"q":"6","answer":"B","options":["coin","soul","road","clock"],"explanation":"a second soul 第二个灵魂。"},{"q":"7","answer":"C","options":["refuse","doubt","accept","ignore"],"explanation":"now I fully accept it 如今我完全接受。"},{"q":"8","answer":"D","options":["boring","silent","empty","surprising"],"explanation":"the most surprising part 最令人惊讶的部分。"},{"q":"9","answer":"A","options":["What","That","Whether","Why"],"explanation":"主语从句缺主语 → What matters is…。"},{"q":"10","answer":"B","options":["price","lesson","noise","weather"],"explanation":"The lesson is that… 表语从句结构。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'Should We Learn More Than English?', 'Last week our class held a debate on a simple question: is English the only foreign language (1)____ learning? Those who said yes argued that English is already used in business, science, and (2)____ communication around the world. Their (3)____ was that one global language is enough for everyone. The other side, however, made a (4)____ point. They said that every language is a key that (5)____ a different world for us. (6)____ we learn French, Japanese, or Arabic, each new language lets us reach more people and (7)____ more cultures. One girl said that to give up other languages would be to make our minds (8)____. In the end, most of us agreed (9)____ English alone is not enough. The real (10)____ is whether our school can offer more language courses in the future.', 135, 2, '[{"q":"1","answer":"C","options":["busy","afraid","worth","ready"],"explanation":"worth learning 值得学习。"},{"q":"2","answer":"D","options":["silent","empty","cheap","international"],"explanation":"international communication 国际交流。"},{"q":"3","answer":"A","options":["belief","price","noise","engine"],"explanation":"Their belief was that… 他们的看法是。"},{"q":"4","answer":"B","options":["silent","strong","empty","sleepy"],"explanation":"made a strong point 提出有力观点。"},{"q":"5","answer":"C","options":["closes","breaks","unlocks","sells"],"explanation":"a key that unlocks a world 开启世界的钥匙。"},{"q":"6","answer":"D","options":["That","What","Why","Whether"],"explanation":"whether…or… 不论……还是。"},{"q":"7","answer":"A","options":["appreciate","forget","lose","sell"],"explanation":"appreciate more cultures 欣赏更多文化。"},{"q":"8","answer":"B","options":["richer","smaller","louder","faster"],"explanation":"make our minds smaller 让头脑变得狭小。"},{"q":"9","answer":"C","options":["whether","what","that","why"],"explanation":"agreed that… 宾语从句陈述观点 → that。"},{"q":"10","answer":"D","options":["price","weather","noise","question"],"explanation":"The real question is whether… 真正的问题在于能否。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'The Power of Kind Words', 'What was the most beautiful thing someone ever said to you? It could have been a single sentence that (1)____ your whole day, or even your year. There is far more to language than spelling and (2)____. Words carry a real power. The kind things people say to us, and the thoughts we hear in our own (3)____, slowly add up and shape our personal stories. Those stories, in turn, help to (4)____ who we are. This is the quiet power of language. If you pay (5)____ to the exact words people choose, you will see how each language (6)____ in the world it builds. You can also feel this power when you (7)____ a negative sentence with a positive one. Saying ''I want to feel secure'' instead of ''I don''t want to fail'' can (8)____ how you feel inside. The (9)____ is that the words we speak do not just describe our lives; they help to (10)____ them. So choose your words with care.', 165, 2, '[{"q":"1","answer":"A","options":["affected","sold","cooked","threw"],"explanation":"a sentence that affected your day 影响你一天的句子。"},{"q":"2","answer":"B","options":["traffic","grammar","weather","money"],"explanation":"spelling and grammar 拼写与语法。"},{"q":"3","answer":"C","options":["cars","shops","minds","gardens"],"explanation":"the thoughts in our own minds 我们心中的想法。"},{"q":"4","answer":"D","options":["sell","hide","waste","determine"],"explanation":"help to determine who we are 帮助决定我们是谁。"},{"q":"5","answer":"A","options":["attention","money","prices","tickets"],"explanation":"pay attention to 关注。"},{"q":"6","answer":"B","options":["sleeps","differs","eats","sells"],"explanation":"how each language differs 每种语言如何不同。"},{"q":"7","answer":"C","options":["forget","drop","replace","lose"],"explanation":"replace A with B 用 B 替换 A。"},{"q":"8","answer":"D","options":["sell","hide","cook","change"],"explanation":"change how you feel 改变你的感受。"},{"q":"9","answer":"A","options":["point","price","noise","weather"],"explanation":"The point is that… 表语从句结构。"},{"q":"10","answer":"B","options":["sell","shape","break","lose"],"explanation":"help to shape them 帮助塑造它们。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U2', 'Guiding Your Audience', 'A good speaker is a little like a guide leading people along a path. As you move from one idea to the (1)____, you must show your audience the way, or they may get lost. The best presenters do this by using small (2)____ such as ''now that I have explained this'' or ''let me turn to that''. These words are called transitions, and they quietly (3)____ what idea is coming next. Without them, even a (4)____ talk can be hard to follow. (5)____ you are speaking about science or history, clear signposts help your listeners (6)____ your argument step by step. Good transitions also give you, the speaker, a moment to (7)____ your thoughts. (8)____ makes a talk truly clear is not only strong ideas but smooth links between them. So before your next presentation, plan (9)____ you will move from point to point. The (10)____ is that the audience should never have to wonder where you are taking them.', 161, 2, '[{"q":"1","answer":"C","options":["price","noise","next","garden"],"explanation":"from one idea to the next 从一个想法到下一个。"},{"q":"2","answer":"D","options":["prices","engines","tickets","phrases"],"explanation":"small phrases 一些短语。"},{"q":"3","answer":"A","options":["signal","sell","hide","break"],"explanation":"signal what idea is coming 提示下一个想法。"},{"q":"4","answer":"B","options":["silent","brilliant","empty","cheap"],"explanation":"even a brilliant talk 即使是精彩的演讲。"},{"q":"5","answer":"C","options":["That","What","Whether","Why"],"explanation":"whether…or… 不论……还是。"},{"q":"6","answer":"D","options":["forget","lose","drop","follow"],"explanation":"follow your argument 跟上你的论证。"},{"q":"7","answer":"A","options":["organise","sell","hide","throw"],"explanation":"organise your thoughts 整理思路。"},{"q":"8","answer":"B","options":["That","What","Whether","Why"],"explanation":"主语从句缺主语 → What makes a talk clear is…。"},{"q":"9","answer":"C","options":["why","whether","how","what"],"explanation":"plan how you will move 计划如何过渡 → how。"},{"q":"10","answer":"D","options":["price","noise","weather","goal"],"explanation":"The goal is that… 表语从句结构。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·对话 Which Language Will You Choose', '上外版选择性必修第二册 U2 · dialogue', 3, 'Lily: Have you decided which foreign language to take next year, Tom?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 Languages in Australia', '上外版选择性必修第二册 U2 · passage', 2, 'Long ago, hundreds of different languages were spoken across Australia.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·对话 Two Words for Blue', '上外版选择性必修第二册 U2 · dialogue', 3, 'Anna: Look at these two squares. Are they the same colour or different?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 A Healthier Brain', '上外版选择性必修第二册 U2 · passage', 2, 'Speaking two languages does more than help you talk to more people.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·对话 Saving Grandpa''s Dialect', '上外版选择性必修第二册 U2 · dialogue', 3, 'Mei: My grandpa speaks an old dialect that almost no young people use now.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U2 听力·短文 Why You Think the Way You Do', '上外版选择性必修第二册 U2 · passage', 2, 'We have seen that speakers of different languages can think in different ways.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write an argumentative letter about learning another foreign language(就再开一门外语写议论性书信)', 'Is English the Only Foreign Language Worth Learning?', '假设你是陈凯,你校只教英语一门外语。你希望学校能再开设一门法语课。请用英语给校长写一封约100–120词的劝说信,内容包括:① 明确提出你的主张(claim):高中生应有机会学习英语以外的语言;② 先承认对方可能的反方观点(counterclaim),再加以反驳;③ 给出一两条具体理由(如能与更多人交流、打开新世界);④ 礼貌地提出请求。注意:用上主语从句/表语从句让说理更清楚。', 'Suppose you are Chen Kai, and your school teaches only English as a foreign language. Write a letter (about 100–120 words) to your headmaster to persuade him to offer a French course. Include: 1) a clear claim that students should be able to learn languages other than English; 2) a likely counterclaim, which you then answer; 3) one or two concrete reasons; 4) a polite request. Try to use subject or predicative clauses to make your argument clear.', '["明确主张(I strongly believe that students should …)","承认并反驳反方观点(It is true that … However, …)","给出具体理由(What a new language offers is …)","礼貌请求(I would be grateful if the school could …)"]'::jsonb, 70, 100, 'Dear Headmaster,
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U2', '{"title":"主语从句 & 表语从句速查","intro":"主语从句和表语从句都是名词性从句:主语从句作句子主语,表语从句跟在系动词 be 后作表语。难点是选连接词。口诀:陈述完整事实→that;表''是否''→whether(不用 if);从句缺主语/宾语→what;问方式/程度→how;问原因→why。","table":{"headers":["连接词","用法 / 例句"],"rows":[["that","从句完整、陈述事实:That language shapes thought is clear. / The truth is that words matter."],["whether","表''是否''的疑问:Whether it is true is unknown. / The question is whether we can.（不用 if）"],["what","从句缺主语或宾语:What matters is… / This is what language does（缺宾语）"],["how","问方式/程度:How the brain learns is amazing. / It is amazing how quickly they react."],["why","问原因:Why so many languages die is a mystery. / That is why he gave up."]]},"specialRules":[{"rule":"主语从句嫌句首太长 → 用 it 作形式主语,真主语后置","mark":"It is true that… = That… is true"},{"rule":"主语从句作主语,谓语一律用单数","mark":"What we say matters（is/matters，不用 are）"},{"rule":"主语/表语从句表''是否''只能用 whether,不用 if","mark":"Whether… is the question √ / If… ×"},{"rule":"The reason is + 表语从句,用 that，不用 why","mark":"The reason is that… √ / The reason is why… ×（但 That is why… √）"}],"why":["选词只看两点:① 从句缺不缺成分——缺主语/宾语就用 what(它本身在从句里当主语或宾语);不缺就在 that/whether/how/why 里按句意挑。② 句意是陈述事实(that)、还是疑问''是否''(whether)、方式(how)、原因(why)。"],"gaokaoPoints":["语法填空高频:句首主语从句或 be 后表语从句中填连接词,先看从句是否缺主宾,再看句意。","易错点:表''是否''用 whether 不用 if;The reason is that…(不用 why);what 引导的主语从句谓语用单数。"],"examVsReal":[{"exam":"What I want to say is that language shapes us.（考试/书面完整）","real":"The thing is, language shapes us.","note":"口语常用 ''The thing is,'' 起头,省去完整的主/表语从句结构。"},{"exam":"Whether it is true remains unknown.（考试用 whether）","real":"We don''t really know if it''s true.","note":"宾语位置口语可用 if;但主语/表语从句仍须用 whether。"}]}'::jsonb, 'sufe');
